// Format WhatsApp message based on order status
const orderData = $input.first().json.order_data;
const customerData = $input.first().json.customer_data;
const status = $input.first().json.status;

// Helper function to format order items
function formatOrderItems(items) {
  if (!items || items.length === 0) {
    return 'Custom sneaker order';
  }

  return items.map(item => {
    const customization = item.customization_details 
      ? Object.entries(item.customization_details)
          .map(([key, value]) => `${key}: ${value}`)
          .join(', ')
      : '';
    const customText = customization ? ` (${customization})` : '';
    const productName = item.products?.name || 'Custom Item';
    return `• ${productName}${customText} - $${item.item_total}`;
  }).join('\n');
}

// Format confirmation message
function formatConfirmationMessage(order, customer) {
  const itemsList = formatOrderItems(order.order_items);
  const orderRef = order.id.slice(0, 8).toUpperCase();

  return `🎉 *Order Confirmed - SneakLab*

Hey ${customer.name}! 

Great news! We've reviewed your custom order #${orderRef} and it's totally doable! 💪

*Your Custom Items:*
${itemsList}

*Total: $${order.total_amount}*

We're starting work on your custom sneakers right now. Our team will craft them with love and attention to detail.

*Delivery:* Hand delivery to your address
*Payment:* Cash on delivery

We'll message you here when your sneakers are ready for pickup! 

Questions? Just reply! 👟✨`;
}

// Format ready message
function formatReadyMessage(order, customer) {
  const addressString = typeof customer.address === 'object' 
    ? `${customer.address.street}\n${customer.address.city}, ${customer.address.state} ${customer.address.zip}`
    : customer.address || 'Address on file';

  const orderRef = order.id.slice(0, 8).toUpperCase();

  return `🎊 *Your Custom Sneakers Are Ready!*

Hi ${customer.name}! 

Your custom order #${orderRef} is complete and ready for delivery! 🔥

*Total Amount: $${order.total_amount}*
*Payment: Cash on delivery*

*Delivery Address:*
${addressString}

Our team will contact you shortly to arrange the hand delivery. Please have the exact amount ready.

Can't wait for you to see your custom kicks! 👟🎨

Reply here if you need to change anything!`;
}

// Generate message based on status
let message;
if (status === 'confirmed') {
  message = formatConfirmationMessage(orderData, customerData);
} else if (status === 'ready') {
  message = formatReadyMessage(orderData, customerData);
} else {
  throw new Error(`Unsupported status: ${status}`);
}

// Clean phone number (remove any non-numeric characters except +)
const cleanPhone = customerData.phone ? customerData.phone.replace(/[^\d+]/g, '') : null;

if (!cleanPhone) {
  throw new Error('Customer phone number is required');
}

return {
  messaging_product: "whatsapp",
  to: cleanPhone,
  type: "text",
  text: { body: message },
  // Additional data for logging
  order_id: orderData.id,
  customer_name: customerData.name,
  status: status
};
